# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜRTÜNMESİZ ORTAMDA ENERJİ DÖNÜŞÜMÜ VE KORUNUMU (SARKAÇ)</text>\n  <rect x="30" y="48" width="400" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <line x1="150" y1="62" x2="310" y2="62" stroke="#1e293b" stroke-width="3"/>\n  <line x1="230" y1="62" x2="120" y2="125" stroke="#64748b" stroke-width="2" stroke-dasharray="4,3"/>\n  <line x1="230" y1="62" x2="230" y2="170" stroke="#1e293b" stroke-width="2"/>\n  <line x1="230" y1="62" x2="340" y2="125" stroke="#64748b" stroke-width="2" stroke-dasharray="4,3"/>\n  <circle cx="120" cy="125" r="16" fill="#3b82f6"/>\n  <text x="120" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">K</text>\n  <circle cx="230" cy="170" r="16" fill="#22c55e"/>\n  <text x="230" y="175" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">L</text>\n  <circle cx="340" cy="125" r="16" fill="#ef4444"/>\n  <text x="340" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">M</text>\n  <text x="95" y="160" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Ep = En Büyük</text>\n  <text x="95" y="175" text-anchor="middle" font-size="10.5" fill="#334155">Ek = 0 (Anlık durur)</text>\n  <text x="230" y="205" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Ek = En Büyük (En hızlı)</text>\n  <text x="230" y="220" text-anchor="middle" font-size="10.5" fill="#334155">Ep = En Küçük</text>\n  <text x="365" y="160" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">Ep = En Büyük</text>\n  <text x="365" y="175" text-anchor="middle" font-size="10.5" fill="#334155">Ek = 0 (Aynı h yüksekliği)</text>\n  <rect x="445" y="48" width="225" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="557" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Enerjinin Korunumu İlkesi</text>\n  <text x="460" y="102" font-size="11.5" fill="#334155">• K → L giderken: Yükseklik</text>\n  <text x="470" y="118" font-size="11" fill="#475569">azalır (Ep ↓), sürat artar (Ek ↑).</text>\n  <text x="460" y="144" font-size="11.5" fill="#334155">• L → M giderken: Sürat azalır</text>\n  <text x="470" y="160" font-size="11" fill="#475569">(Ek ↓), yükseklik artar (Ep ↑).</text>\n  <rect x="460" y="178" width="195" height="45" rx="6" fill="#dcfce7" stroke="#16a34a"/>\n  <text x="557" y="198" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Toplam Mekanik Enerji</text>\n  <text x="557" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">E_toplam = Ep + Ek = SABİT</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAY SİSTEMLERİNDE ENERJİ DÖNÜŞÜMÜ VE SÜRTÜNME ETKİSİ</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Esneklik Potansiyeli ↔ Kinetik Enerji</text>\n  <text x="48" y="104" font-size="11.5" fill="#334155">1. Sıkıştırılmış yay önüne konulan bilye:</text>\n  <text x="60" y="124" font-size="11" font-weight="bold" fill="#92400e">Esneklik Potansiyel Enerjisi → Kinetik Enerji</text>\n  <text x="48" y="152" font-size="11.5" fill="#334155">2. Yüksekten yay üzerine düşen cisim:</text>\n  <text x="60" y="172" font-size="11" font-weight="bold" fill="#92400e">Çekim Potansiyeli → Kinetik → Esneklik Pot.</text>\n  <text x="48" y="200" font-size="11.5" fill="#334155">3. Sırıkla yüksek atlama yapan sporcu:</text>\n  <text x="60" y="218" font-size="11" fill="#475569">Kinetik → Esneklik Pot. → Çekim Potansiyeli</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Sürtünmeli Ortamda Enerji Korunumu</text>\n  <text x="378" y="104" font-size="11.5" fill="#334155">• Sürtünme kuvveti hareketi zorlaştırır ve</text>\n  <text x="388" y="122" font-size="11.5" font-weight="bold" fill="#991b1b">kinetik enerjiyi ısı enerjisine dönüştürür.</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">• Mekanik enerji (Ep + Ek) zamanla azalır;</text>\n  <text x="388" y="166" font-size="11" fill="#475569">fakat ısıya dönüşen enerji dahil edildiğinde</text>\n  <text x="388" y="184" font-size="11.5" font-weight="bold" fill="#15803d">TOPLAM ENERJİ YİNE KORUNUR!</text>\n  <text x="515" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Fren yapan aracın tekerleklerinin ısınması</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HAVA DİRENCİ VE SU DİRENCİ (AKIŞKAN SÜRTÜNMESİ)</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hava Direnci (Hava Sürtünmesi)</text>\n  <text x="48" y="102" font-size="11.5" fill="#334155">• Havada hareket eden cisimlere hareket</text>\n  <text x="58" y="120" font-size="11" fill="#475569">yönüne zıt yönde etki eden sürtünmedir.</text>\n  <text x="48" y="146" font-size="11.5" font-weight="bold" fill="#1e40af">Azaltmak İçin (Aerodinamik Tasarım):</text>\n  <text x="58" y="164" font-size="11" fill="#334155">Uçak, hızlı tren ve yarış arabalarının</text>\n  <text x="58" y="180" font-size="11" fill="#334155">ön kısmının sivri (V biçimli) yapılması.</text>\n  <text x="48" y="204" font-size="11.5" font-weight="bold" fill="#15803d">Artırmak İçin:</text>\n  <text x="135" y="204" font-size="11" fill="#334155">Geniş yüzeyli paraşüt kullanmak.</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Su Direnci (Su Sürtünmesi)</text>\n  <text x="378" y="102" font-size="11.5" fill="#334155">• Su içindeki cisimlerin hareketini zorlaştıran</text>\n  <text x="388" y="120" font-size="11" fill="#475569">ve kinetik enerjisini azaltan dirençtir.</text>\n  <text x="378" y="146" font-size="11.5" fill="#334155">• Su tanecikleri havadan daha sık olduğu için</text>\n  <text x="388" y="164" font-size="11.5" font-weight="bold" fill="#166534">Su Direnci &gt; Hava Direnci</text>\n  <text x="378" y="190" font-size="11.5" font-weight="bold" fill="#15803d">Azaltmak İçin:</text>\n  <text x="388" y="208" font-size="11" fill="#334155">Gemilerin burnunun V şeklinde yapılması,</text>\n  <text x="388" y="224" font-size="11" fill="#334155">balıkların kaygan pul ve ince vücut yapısı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
